head.script:
scwin.onpageload = function() {

var jsonData = [
    {
        "kofileCrtrYmd": "2020.01.08",
        "csDvsTaskNm": "원고",
        "ofdocNm": "빈소장",
        "prog1": "",
        "prog2": "",
        "prog3": "",
        "prog4": "",
        "prog5": "",
        "dltMenu": ""
    },
    {
        "kofileCrtrYmd": "2020.01.08",
        "csDvsTaskNm": "원고",
        "ofdocNm": "문서제출명령",
        "prog1": "",
        "prog2": "",
        "prog3": "",
        "prog4": "",
        "prog5": "",
        "dltMenu": ""
    },
    {
        "kofileCrtrYmd": "2020.01.16",
        "csDvsTaskNm": "원고",
        "ofdocNm": "답변서",
        "prog1": "",
        "prog2": "",
        "prog3": "",
        "prog4": "",
        "prog5": "",
        "dltMenu": ""
    },
    {
        "kofileCrtrYmd": "2020.01.16",
        "csDvsTaskNm": "원고",
        "ofdocNm": "문서제출명령",
        "prog1": "",
        "prog2": "",
        "prog3": "",
        "prog4": "",
        "prog5": "",
        "dltMenu": ""
    }
]
dataList1.setJSON(jsonData);
gridView1.setCellDisabled(0,"dltMenu","true");//0번째 row 상세메뉴 disabled
gridView1.setCellDisabled(1,"dltMenu","true");//1번째 row 상세메뉴 disabled

var info = {inputType : "link",
options : {}
};
gridView1.setCellInputType(0, 'ofdocNm', info);
gridView1.setCellInputType(1, 'ofdocNm', info);
gridView1.setCellInputType(2, 'ofdocNm', info);
gridView1.setCellInputType(3, 'ofdocNm', info);
gridView1.setCellInputType(4, 'ofdocNm', info);



//gridView2.setCellDisabled(0,"dltMenu","true");//0번째 row 상세메뉴 disabled
//gridView2.setCellDisabled(1,"dltMenu","true");//0번째 row 상세메뉴 disabled

};

	scwin.setSimulate = function() {
		scwin.simulateWrapper('#gridView1_link_0_2', 'key-combo', {
			combo: 'TAB'
		});
	}
	scwin.setSimulateBack = function() {
		scwin.simulateWrapper('#gridView1_link_0_2', 'key-combo', {
			combo: 'shift+TAB'
		});
	}	
	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}

	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('gridView1_cell_1_2').classList.contains('focusedTd');
	}	
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('gridView1_cell_2_2').classList.contains('focusedTd');
	}	
	scwin.checkVal3 = function() {
		return WebSquare.wUnit.getDomById('gridView1_cell_2_8').classList.contains('focusedTd');
	}	
	scwin.checkVal4 = function() {
		return WebSquare.wUnit.getDomById('gridView1_cell_3_2').classList.contains('focusedTd');
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_link_0_2').click()");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
		WebSquare.wUnit.addCommand('pause', '500');	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
		WebSquare.wUnit.addCommand('pause', '500');
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
		WebSquare.wUnit.addCommand('pause', '500');	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
		WebSquare.wUnit.addCommand('pause', '500');		
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal4()", "true");
		WebSquare.wUnit.addCommand("pause", "500");			
		WebSquare.wUnit.addCommand("set", "scwin.setSimulateBack()");
		WebSquare.wUnit.addCommand('pause', '500');			
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
